import React from "react";
import Layout from "../components/Layout";

const watchlist = [
  { ticker: "AAPL", company: "Apple", symbol: "NASDAQ-AAPL" },
  { ticker: "MSFT", company: "Microsoft", symbol: "NASDAQ-MSFT" },
  {
    ticker: "VTI",
    company: "Vanguard Total Stock Market ETF",
    symbol: "AMEX-VTI",
  },
  { ticker: "GOOGL", company: "Alphabet", symbol: "NASDAQ-GOOGL" },
  { ticker: "NVDA", company: "NVIDIA", symbol: "NASDAQ-NVDA" },
];

// The URL and fragment match the iframe generated by TradingView's Market Data embed.
// Keep the vendor document cross-origin so it cannot read the app's session or ledger.
const widgetUrl = new URL("https://www.tradingview-widget.com/embed-widget/market-quotes/?locale=en");
widgetUrl.hash = encodeURIComponent(JSON.stringify({
  width: "100%",
  height: 320,
  showSymbolLogo: true,
  symbolsGroups: [{
    name: "U.S. watchlist",
    symbols: watchlist.map(({ symbol, company }) => ({ name: symbol.replace("-", ":"), displayName: company })),
  }],
  colorTheme: "light",
}));

const MarketQuotesPage = () => (
  <Layout>
    <div className="space-y-6">
      <div>
        <h1 className="font-display text-3xl font-semibold text-ink">
          Market Quotes
        </h1>
        <p className="mt-2 max-w-2xl text-ink/70">
          TradingView provides delayed USD quotes for five U.S. stocks and funds.
          Availability varies by symbol.
        </p>
      </div>

      <section
        aria-labelledby="watchlist-heading"
        className="rounded-3xl bg-white/80 p-4 shadow-card sm:p-6"
      >
        <div className="flex flex-wrap items-baseline justify-between gap-x-4 gap-y-2">
          <h2
            id="watchlist-heading"
            className="font-display text-xl font-semibold text-ink"
          >
            U.S. watchlist
          </h2>
          <a
            className="text-sm font-semibold text-ink/80 underline underline-offset-4"
            href="https://www.tradingview.com/markets/"
            target="_blank"
            rel="noopener noreferrer"
          >
            Data by TradingView
          </a>
        </div>
        <iframe
          title="TradingView quotes for AAPL, MSFT, VTI, GOOGL and NVDA"
          src={widgetUrl.href}
          sandbox="allow-scripts allow-same-origin allow-popups allow-popups-to-escape-sandbox"
          referrerPolicy="no-referrer"
          className="mt-4 block h-[330px] w-full rounded-2xl border border-ink/10 bg-white"
        />
        <p className="mt-4 text-sm text-ink/70">
          If the table is unavailable, open a quote directly on TradingView:
        </p>
        <ul className="mt-2 flex flex-wrap gap-2">
          {watchlist.map(({ ticker, company, symbol }) => (
            <li key={symbol}>
              <a
                aria-label={`${ticker} (${company}) on TradingView, opens in a new tab`}
                className="inline-flex min-h-10 items-center rounded-full border border-ink/20 px-3 text-sm font-semibold text-ink transition hover:bg-fog"
                href={`https://www.tradingview.com/symbols/${symbol}/`}
                target="_blank"
                rel="noopener noreferrer"
              >
                {ticker}
              </a>
            </li>
          ))}
        </ul>
      </section>

      <p className="rounded-2xl border border-copper/25 bg-white/80 px-5 py-4 text-sm text-ink/80">
        Portfolio valuations use a separate feed. Your portfolio shows which
        prices it uses, including when it uses sample prices.
      </p>
    </div>
  </Layout>
);

export default MarketQuotesPage;
